mapper.delete:
DELETE FROM trip WHERE trip_id IN (
  SELECT trip_id FROM trip
  WHERE member_id = #{memberId} AND deleted_at IS NOT NULL
  ORDER BY deleted_at DESC, trip_id DESC
  OFFSET #{keep}
)

mapper.select:
SELECT 
FROM trip_stop
WHERE trip_id = #{tripId} AND stop_id = #{stopId}

mapper.update:
UPDATE trip_stop
SET day_no = #{day}, start_time = #{time}, stay_min = #{stay}, fixed = #{fixed},
    move_mode = #{mode}, memo = #{memo}, state = #{state}, importance = #{importance}
WHERE trip_id = #{tripId} AND stop_id = #{id}

UPDATE trip_stop SET state = #{state}
WHERE trip_id = #{tripId} AND stop_id IN
#{stopId}
